1 void reverse_list(){
2    // No need to reverse if there is 0 or 1 Node.
3    if (get_length() < 2) return;
4    // Start from the head node;
5    Node<T>* current = head;
6    Node<T>* prev_node = nullptr;
7
8    while (true){
9       // Traverse the list from head to tail
10       prev_node = current->prev;
11       current->prev = current->next;
12       current->next = prev_node;
13
14       current = current->prev;
15       // Stop if we reach the end
16       if (current == nullptr) break;
17     }
18     // Swap head and tail
19     Node<T>* temp = head;
20     head = tail;
21     tail = temp;
22 }
